import {ReportedMap} from './DeliveryMap';
import {useRiderTracking} from './RiderTracking';
import {useEffect,useRef,useState} from 'react';
import {api} from './api';
import {AlertSettings,Blank,Feedback,Section} from './common';
import {Field,Form} from './ui';
import {money,timestamp,useResource} from './data';
export function Wallet(){
 const r=useResource(()=>api('/services/wallet')),[currency,setCurrency]=useState('NGN'),[action,setAction]=useState('deposit'),[draft,setDraft]=useState(null),[notice,setNotice]=useState('');
 const demo=r.data?.demo,balance=demo?.balances.find(b=>b.currency===currency)?.amountMinor??0;
 const titles={deposit:'Add demo funds',transfer:'Send demo funds',withdraw:'Withdraw demo funds',received:'Demo funds received'};
 return <><h1>Your DEN wallet.</h1><p className="muted">Try deposits, transfers, and withdrawals with demo funds.</p><p className="notice">Demo only · These funds have no cash value. No card is charged, no bank account is connected, and no real money moves.</p><Feedback resource={r}/>{notice?<p className="notice" role="status">{notice}</p>:null}{demo?.enabled?<><section className="wallet-demo-overview"><div><span>Demo balance · {currency}</span><strong>{money(balance,currency)}</strong><small>Simulated funds, separate from recorded balances</small></div><Field label="Wallet currency"><select value={currency} onChange={e=>{setCurrency(e.target.value);setDraft(null);}}>{demo.currencies.map(c=><option key={c}>{c}</option>)}</select></Field></section><section className="service-panel wallet-demo-actions"><h2>Try your wallet</h2><div className="action-tabs" role="group" aria-label="Demo wallet action">{['deposit','transfer','withdraw'].map(kind=><button className={action===kind?'primary':'secondary'} type="button" aria-pressed={action===kind} key={kind} onClick={()=>{setAction(kind);setDraft(null);setNotice('');}}>{titles[kind]}</button>)}</div>{draft?<div className="wallet-demo-review"><h3>Review demo {draft.kind==='withdraw'?'withdrawal':draft.kind}</h3><p><strong>{money(draft.amountMinor,draft.currency)}</strong>{draft.recipientEmail?` to ${draft.recipientEmail}`:''}</p><p className="muted">{draft.kind==='withdraw'?'This deducts demo funds only. There is no bank payout.':'This is a simulation, not a payment.'}</p><Form submit={`Confirm demo ${draft.kind==='withdraw'?'withdrawal':draft.kind}`} onSubmit={async()=>{try{await api('/services/wallet/demo','POST',draft);}catch(error){const messages={INSUFFICIENT_DEMO_BALANCE:'You do not have enough demo funds in this currency.',DEMO_RECIPIENT_NOT_FOUND:'No active DEN account matches that email.',SELF_TRANSFER_NOT_ALLOWED:'Choose another DEN account to receive this demo transfer.',IDEMPOTENCY_CONFLICT:'This request changed. Cancel and review a new demo transaction.',DEMO_WALLET_CHANGED_RETRY:'The wallet changed. Try again with the same details.'};throw new Error(messages[error.code]??error.message);}setNotice(`Demo ${draft.kind==='withdraw'?'withdrawal':draft.kind} completed. No real money moved.`);setDraft(null);await r.refresh();window.dispatchEvent(new Event('den:wallet-updated'));}}><button type="button" className="secondary" onClick={()=>setDraft(null)}>Cancel</button></Form></div>:<Form key={`${action}:${currency}`} submit="Review demo transaction" onSubmit={async d=>{const value=String(d.amount).trim();if(!/^\d{1,6}(\.\d{1,2})?$/.test(value))throw new Error('Enter an amount with at most two decimal places.');const [major,fraction='']=value.split('.'),amountMinor=Number(major)*100+Number(fraction.padEnd(2,'0'));if(amountMinor<=0||amountMinor>demo.maxAmountMinor)throw new Error(`Enter an amount between ${money(1,currency)} and ${money(demo.maxAmountMinor,currency)}.`);if(action!=='deposit'&&amountMinor>Number(balance))throw new Error('Add demo funds first or enter an amount within your demo balance.');setDraft({kind:action,currency,amountMinor,...(action==='transfer'?{recipientEmail:d.recipientEmail.trim().toLowerCase()}:{}),idempotencyKey:crypto.randomUUID()});}}><Field label={`Amount (${currency})`} name="amount" inputMode="decimal" placeholder="0.00" required autoComplete="off"/>{action==='transfer'?<Field label="Recipient DEN email" name="recipientEmail" type="email" required maxLength={254} autoComplete="off"/>:null}<p className="small muted">{action==='deposit'?'Add simulated funds without a card or bank.':action==='transfer'?'Send simulated funds to another existing DEN account.':'Deduct simulated funds without a bank payout.'}</p></Form>}</section><Section title="Demo transaction history" action={<button type="button" className="text-button" onClick={r.refresh}>Refresh</button>}>{demo.entries.length?<ul className="event-list wallet-demo-history">{demo.entries.map(e=><li key={e.id}><div><strong>{{deposit:'Demo deposit',transfer:'Demo transfer sent',withdraw:'Demo withdrawal',received:'Demo transfer received'}[e.kind]??'Demo transaction'}</strong><small>{timestamp(e.createdAt)} · Demo only</small></div><strong className={e.amountMinor>0?'wallet-credit':'wallet-debit'}>{e.amountMinor>0?'+':''}{money(e.amountMinor,e.currency)}</strong></li>)}</ul>:<Blank title="No demo transactions yet.">Add demo funds to try the wallet.</Blank>}</Section></>:r.data?<p className="notice">Demo wallet is not available yet. Refresh to check again.</p>:null}{r.data?.balances.length?<Section title="Other recorded balances"><p className="muted">These records are separate from the demo wallet and cannot be spent here.</p><div className="wallet-grid">{r.data.balances.map(b=><div className="wallet-card" key={b.currency}><span>{b.currency}</span><strong>{money(b.amountMinor,b.currency)}</strong></div>)}</div></Section>:null}{r.data?.entries.length?<Section title="Other recorded transactions"><ul className="event-list">{r.data.entries.map(e=><li key={e.id}><strong>{money(e.amountMinor,e.currency)}</strong><p>{e.reference}</p><small>{timestamp(e.createdAt)}</small></li>)}</ul></Section>:null}<AlertSettings/></>;
}
export function OrderServices({id,role}){
 const [panel,setPanel]=useState(''),[channel,setChannel]=useState(role==='consumer'?'rider_consumer':'manager_rider');
 return <section className="order-actions"><h3>Delivery coordination</h3><div className="action-tabs"><button className={`secondary ${panel==='tracking'?'chosen':''}`} onClick={()=>setPanel(panel==='tracking'?'':'tracking')}>OneTrack</button><button className={`secondary ${panel==='chat'?'chosen':''}`} onClick={()=>setPanel(panel==='chat'?'':'chat')}>Order chat</button></div>{panel==='tracking'?<Tracking id={id} role={role}/>:null}{panel==='chat'?<>{role==='rider'?<Field label="Conversation"><select value={channel} onChange={e=>setChannel(e.target.value)}><option value="rider_consumer">Assigned customer</option><option value="manager_rider">Organization manager</option></select></Field>:null}<OrderChat key={channel} id={id} channel={channel}/></>:null}<p className="small muted">Location and chat require an active assigned delivery. Consumers cannot privately message organizations.</p></section>;
}
function Tracking({id,role}){
 const r=useResource(()=>api(`/services/orders/${id}/tracking`),[id]),tracking=useRiderTracking();
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)void r.refresh();},15000);return()=>clearInterval(timer);},[r.refresh]);
 const sharing=tracking?.active&&tracking.orderId===id;
 return <div className="service-panel"><h3>Delivery GPS</h3><Feedback resource={r}/>{r.data&&!r.error?<><p>Status: <strong>{r.data.state==='reported'?'GPS received':r.data.state==='stale'?'Last location is out of date':r.data.state==='simulated'?'Simulated location':'Waiting for GPS'}</strong></p><ReportedMap point={r.data.point} stale={r.data.state==='stale'} simulated={r.data.state==='simulated'}/></>:null}<p className="small muted">Updates refresh every 15 seconds. ETA and traffic are not connected.</p>{role==='rider'?<><p className="small muted">Starting shares your precise GPS with this delivery’s customer. Keep DEN open and this tab visible. Sharing continues when you close this panel or change pages inside this workspace; it stops when you sign out, close DEN, stop sharing, or the assignment ends. Phone lock and background tracking are not supported.</p>{tracking?.active&&tracking.orderId!==id?<p className="notice">You are sharing GPS for another delivery. Stop sharing there before starting this order.</p>:null}<button type="button" className={sharing?'secondary':'primary'} disabled={!sharing&&(!r.data||(tracking?.active&&tracking.orderId!==id))} onClick={()=>sharing?tracking.stop():tracking.start(id)}>{sharing?'Stop sharing GPS':'Start sharing GPS'}</button>{tracking?.orderId===id?<p className="small" role="status">{tracking.message}</p>:null}</>:<p className="small muted">Your assigned rider must turn on GPS sharing. Old or missing positions are shown as unavailable rather than as a live location.</p>}<button type="button" className="text-button" onClick={r.refresh}>Refresh location</button></div>;
}

function OrderChat({id,channel}){
 const r=useResource(()=>api(`/services/orders/${id}/messages?channel=${channel}`),[id,channel]),key=useRef(crypto.randomUUID());
 return <div className="service-panel"><h3>{channel==='rider_consumer'?'Rider and customer':'Manager and rider'}</h3><Feedback resource={r}/>{r.data?<><button className="text-button" onClick={r.refresh}>Refresh conversation</button>{r.data.messages.length?<ul className="event-list">{[...r.data.messages].reverse().map(m=><li key={m.id}><p>{m.text}</p><small>{timestamp(m.createdAt)}</small></li>)}</ul>:<p className="muted">No messages yet.</p>}<Form submit="Send message" onSubmit={async d=>{await api(`/services/orders/${id}/messages?channel=${channel}`,'POST',{text:d.text,idempotencyKey:key.current});key.current=crypto.randomUUID();await r.refresh();}}><Field label="Message"><textarea name="text" required maxLength={4000}/></Field></Form></>:null}</div>;
}
